import { describe, expect, it } from 'vitest';
import { formatSql, highlightSql, type SqlToken } from './sql';

// Real SQL generated by the agent / evaluator (single-line, as returned by the backend).
const TOP5 =
  'SELECT t1.holding_id, t2.symbol, t2.company_name, t1.quantity, t1.cost_basis FROM holdings AS t1 JOIN securities AS t2 ON t1.security_id = t2.security_id JOIN portfolios AS t3 ON t1.portfolio_id = t3.portfolio_id WHERE t3.portfolio_name = ? ORDER BY t1.cost_basis DESC LIMIT ?';
const COUNT = 'SELECT COUNT(*) FROM portfolios';
const CTE =
  "WITH portfolio_totals AS (SELECT p.portfolio_id, SUM(h.quantity * s.current_price) AS total_value FROM portfolios p JOIN holdings h ON p.portfolio_id = h.portfolio_id AND h.quantity > 0 GROUP BY p.portfolio_id) SELECT pt.portfolio_name, ROUND((pt.total_value * 100.0) / 5, 2) AS pct, CASE WHEN pt.x > 1 THEN 'a' ELSE 'b' END AS band FROM portfolio_totals pt LEFT JOIN tech th ON pt.portfolio_id = th.portfolio_id WHERE pt.portfolio_name = ? AND pt.y IN (1,2) ORDER BY pct DESC LIMIT ?";
const ALL = [TOP5, COUNT, CTE];

const squash = (s: string) => s.replace(/\s+/g, '');
const lineOf = (text: string, needle: string) => text.split('\n').find((l) => l.includes(needle)) ?? '';
const indentOf = (line: string) => line.length - line.trimStart().length;

describe('formatSql layout', () => {
  const out = formatSql(TOP5);
  const lines = out.split('\n');

  it('puts each SELECT column on its own line, indented by 4 spaces', () => {
    for (const col of ['t1.holding_id,', 't2.symbol,', 't2.company_name,', 't1.quantity,', 't1.cost_basis']) {
      const l = lineOf(out, col);
      expect(l.trim()).toBe(col);
      expect(indentOf(l)).toBe(4);
    }
  });

  it('puts FROM and every JOIN on separate lines with the ON condition indented beneath', () => {
    expect(lines).toContain('FROM');
    const join1 = lines.indexOf('    JOIN securities AS t2');
    expect(join1).toBeGreaterThan(-1);
    expect(lines[join1 + 1]).toBe('        ON t1.security_id = t2.security_id');
    const join2 = lines.indexOf('    JOIN portfolios AS t3');
    expect(lines[join2 + 1]).toBe('        ON t1.portfolio_id = t3.portfolio_id');
    expect(lines.join('\n')).not.toMatch(/JOIN .* ON /);
  });

  it('keeps WHERE, ORDER BY and LIMIT as separate clause lines', () => {
    expect(lines).toContain('WHERE');
    expect(lines).toContain('    t3.portfolio_name = ?');
    expect(lines).toContain('ORDER BY');
    expect(lines).toContain('    t1.cost_basis DESC');
    expect(lines[lines.length - 1]).toBe('LIMIT ?');
  });

  it('uses only multiples of 4 spaces for indentation', () => {
    for (const q of ALL) for (const l of formatSql(q).split('\n')) expect(indentOf(l) % 4).toBe(0);
  });

  it('indents further ON conditions under their JOIN and nests CTE bodies', () => {
    const f = formatSql(CTE).split('\n');
    const join = f.findIndex((l) => l.trim() === 'JOIN holdings h');
    expect(f[join + 1]).toBe(`${' '.repeat(indentOf(f[join]) + 4)}ON p.portfolio_id = h.portfolio_id`);
    expect(f[join + 2]).toBe(`${' '.repeat(indentOf(f[join]) + 4)}AND h.quantity > 0`);
    expect(f[0]).toBe('WITH');
    expect(f[1]).toBe('    portfolio_totals AS (');
    expect(f.find((l) => l.includes('GROUP BY'))).toBeDefined();
    expect(f).toContain('LIMIT ?');
  });

  it('formats a simple aggregate over several lines', () => {
    expect(formatSql(COUNT)).toBe('SELECT\n    COUNT(*)\nFROM\n    portfolios');
  });
});

describe('formatting never changes the SQL itself', () => {
  it('differs from the original by whitespace only, with case, literals and placeholders intact', () => {
    for (const q of ALL) {
      const f = formatSql(q);
      expect(squash(f)).toBe(squash(q));
      expect(f.match(/\?/g)?.length ?? 0).toBe(q.match(/\?/g)?.length ?? 0);
    }
  });

  it('is idempotent', () => {
    for (const q of ALL) expect(formatSql(formatSql(q))).toBe(formatSql(q));
  });

  it('does not mutate its input and returns the original text when it cannot format', () => {
    const original = TOP5;
    formatSql(original);
    expect(original).toBe(TOP5);
    expect(formatSql('not really sql ???')).toContain('not really sql');
    expect(formatSql('')).toBe('');
  });

  it('keeps string literals byte-for-byte', () => {
    expect(formatSql("SELECT 'it''s  spaced' FROM t")).toContain("'it''s  spaced'");
  });
});

const roles = (sql: string): Record<string, string> => {
  const map: Record<string, string> = {};
  for (const line of highlightSql(formatSql(sql))) for (const t of line.tokens) if (t.kind !== 'text') map[t.text] ??= t.kind;
  return map;
};

describe('highlightSql roles', () => {
  const r = roles(TOP5);
  it('classifies keywords, tables, aliases, columns and placeholders', () => {
    expect(r['SELECT']).toBe('keyword');
    expect(r['JOIN']).toBe('keyword');
    expect(r['ORDER']).toBe('keyword');
    expect(r['holdings']).toBe('table');
    expect(r['securities']).toBe('table');
    expect(r['t1']).toBe('alias');
    expect(r['t3']).toBe('alias');
    expect(r['cost_basis']).toBe('column');
    expect(r['portfolio_name']).toBe('column');
    expect(r['=']).toBe('operator');
    expect(r['?']).toBe('param');
  });

  it('classifies functions, CTE names, numbers, strings and column aliases', () => {
    const c = roles(CTE);
    expect(c['SUM']).toBe('function');
    expect(c['ROUND']).toBe('function');
    expect(c['portfolio_totals']).toBe('table');
    expect(c['total_value']).toBe('alias');
    expect(c['pct']).toBe('alias');
    expect(c['100.0']).toBe('number');
    expect(c["'a'"]).toBe('string');
    expect(c['CASE']).toBe('keyword');
    expect(c['*']).toBe('operator');
  });

  it('numbers placeholders in order so each can show its bound value', () => {
    const params: SqlToken[] = highlightSql(formatSql(TOP5)).flatMap((l) => l.tokens).filter((t) => t.kind === 'param');
    expect(params.map((t) => t.param)).toEqual([0, 1]);
  });

  it('reproduces the formatted text exactly, line by line, with its indentation', () => {
    for (const q of ALL) {
      const formatted = formatSql(q);
      const rebuilt = highlightSql(formatted).map((l) => ' '.repeat(l.indent) + l.tokens.map((t) => t.text).join('')).join('\n');
      expect(rebuilt).toBe(formatted);
    }
  });
});
